     9	export const systemClock: Clock = {
    10	  now: () => new Date(),
    11	};
    12	
    13	/** A clock frozen at a single instant. `iso` is a full timestamp, e.g. "2026-03-10T09:30:00Z". */
    14	export function fixedClock(iso: string): Clock {
    15	  const at = new Date(iso);
