     1	// Cutoff logic.
     2	//
     3	// The cutoff for a delivery is `cutoffHour` local time, `cutoffDaysBefore` days
     4	// before the delivery date, expressed in the subscription's timezone. After
     5	// that instant the box is locked.
     6	
     7	import type { Subscription } from "./types.ts";
     8	
     9	/** Shift an ISO date string (YYYY-MM-DD) by a whole number of days. Pure calendar math, no timezone. */
    10	export function shiftDate(isoDate: string, days: number): string {
    11	  const [y, m, d] = isoDate.split("-").map(Number);
    12	  // Anchor on UTC noon so daylight-saving transitions can never roll the calendar day.
    13	  const base = Date.UTC(y, m - 1, d, 12, 0, 0);
    14	  const shifted = new Date(base + days * 86_400_000);
    15	  return toIsoDate(shifted);
    16	}
    17	
    18	export function toIsoDate(d: Date): string {
    19	  const y = d.getUTCFullYear();
    20	  const m = String(d.getUTCMonth() + 1).padStart(2, "0");
    21	  const day = String(d.getUTCDate()).padStart(2, "0");
    22	  return `${y}-${m}-${day}`;
    23	}
    24	
    25	/**
    26	 * The instant after which the box for `deliveryDate` is locked.
    27	 *
    28	 * It is `cutoffHour:00` on the cutoff day, interpreted in the subscription's
    29	 * timezone, returned as an absolute instant (a Date).
    30	 */
    31	export function cutoffInstant(deliveryDate: string, sub: Subscription): Date {
    32	  const cutoffDay = shiftDate(deliveryDate, -sub.cutoffDaysBefore);
    33	  const [y, m, d] = cutoffDay.split("-").map(Number);
    34	  // Construct the wall-clock cutoff time and return it as an instant.
    35	  return new Date(y, m - 1, d, sub.cutoffHour, 0, 0, 0);
    36	}
    37	
    38	/** True if `now` is still before the cutoff for `deliveryDate` (the box is still open). */
    39	export function isBeforeCutoff(now: Date, deliveryDate: string, sub: Subscription): boolean {
    40	  return now.getTime() < cutoffInstant(deliveryDate, sub).getTime();
    41	}
