     1	// In-memory store for subscriptions and materialized deliveries.
     2	//
     3	// Deliveries are keyed by the business key `${subscriptionId}:${date}`. The
     4	// store enforces one invariant: a subscription may have at most one delivery
     5	// per date. `schedule` throws if that would be violated.
     6	
     7	import {
     8	  type Delivery,
     9	  type DeliveryStatus,
    10	  type Subscription,
    11	  DuplicateDeliveryError,
    12	  DeliveryNotFoundError,
    13	  UnknownSubscriptionError,
    14	} from "./types.ts";
    15	
    16	function key(subscriptionId: string, date: string): string {
    17	  return `${subscriptionId}:${date}`;
    18	}
    19	
    20	export class Repository {
    21	  private subscriptions = new Map<string, Subscription>();
    22	  private deliveries = new Map<string, Delivery>();
    23	
    24	  addSubscription(sub: Subscription): void {
    25	    this.subscriptions.set(sub.id, sub);
    26	  }
    27	
    28	  getSubscription(id: string): Subscription {
    29	    const sub = this.subscriptions.get(id);
    30	    if (!sub) throw new UnknownSubscriptionError(id);
    31	    return sub;
    32	  }
    33	
    34	  /** Materialize a delivery. Throws if one already exists for this (subscription, date). */
    35	  schedule(subscriptionId: string, date: string): Delivery {
    36	    const sub = this.getSubscription(subscriptionId);
    37	    const k = key(subscriptionId, date);
    38	    if (this.deliveries.has(k)) {
    39	      throw new DuplicateDeliveryError(k);
    40	    }
    41	    const delivery: Delivery = {
    42	      subscriptionId,
    43	      customerId: sub.customerId,
    44	      date,
    45	      status: "scheduled",
    46	    };
    47	    this.deliveries.set(k, delivery);
    48	    return delivery;
    49	  }
    50	
    51	  find(subscriptionId: string, date: string): Delivery | undefined {
    52	    return this.deliveries.get(key(subscriptionId, date));
    53	  }
    54	
    55	  setStatus(subscriptionId: string, date: string, status: DeliveryStatus): Delivery {
    56	    const d = this.deliveries.get(key(subscriptionId, date));
    57	    if (!d) throw new DeliveryNotFoundError(key(subscriptionId, date));
    58	    d.status = status;
    59	    return d;
    60	  }
    61	
    62	  /** All materialized deliveries for a customer, most-recent-first. */
    63	  deliveriesFor(customerId: string): Delivery[] {
    64	    const out: Delivery[] = [];
    65	    for (const d of this.deliveries.values()) {
    66	      if (d.customerId === customerId) out.push(d);
    67	    }
    68	    out.sort((a, b) => (a.date < b.date ? 1 : -1));
    69	    return out;
    70	  }
    71	}
