     1	// Cadence math: turn a subscription into its series of delivery dates, and pick
     2	// the next one a customer can still act on.
     3	
     4	import type { Cadence, Subscription } from "./types.ts";
     5	import { shiftDate, isBeforeCutoff } from "./cutoff.ts";
     6	
     7	function step(date: string, cadence: Cadence): string {
     8	  switch (cadence) {
     9	    case "weekly":
    10	      return shiftDate(date, 7);
    11	    case "biweekly":
    12	      return shiftDate(date, 14);
    13	    case "monthly":
    14	      // Approximate a month as 30 days.
    15	      return shiftDate(date, 30);
    16	  }
    17	}
    18	
    19	/** The first `count` delivery dates at or after `from`, walking the cadence from the anchor. */
    20	export function upcomingDeliveries(sub: Subscription, from: string, count: number): string[] {
    21	  let date = sub.anchorDate;
    22	  while (date < from) {
    23	    date = step(date, sub.cadence);
    24	  }
    25	  const out: string[] = [];
    26	  for (let i = 0; i < count; i++) {
    27	    out.push(date);
    28	    date = step(date, sub.cadence);
    29	  }
    30	  return out;
    31	}
    32	
    33	/**
    34	 * The next delivery the customer can still change — the earliest upcoming
    35	 * delivery whose cutoff has not yet passed as of `now`.
    36	 */
    37	export function nextDeliveryDate(sub: Subscription, now: Date): string {
    38	  const today = nowToIsoDate(now);
    39	  const candidates = upcomingDeliveries(sub, today, 6);
    40	  for (const date of candidates) {
    41	    if (isBeforeCutoff(now, date, sub)) {
    42	      return date;
    43	    }
    44	  }
    45	  // All cutoffs in the window have passed; fall through to the last candidate.
    46	  return candidates[candidates.length - 1];
    47	}
    48	
    49	function nowToIsoDate(now: Date): string {
    50	  const y = now.getUTCFullYear();
    51	  const m = String(now.getUTCMonth() + 1).padStart(2, "0");
    52	  const d = String(now.getUTCDate()).padStart(2, "0");
    53	  return `${y}-${m}-${d}`;
    54	}
