    27	  /** Materialize the next `count` deliveries for a subscription so they can be acted on. */
    28	  scheduleUpcoming(subscriptionId: string, count = 3): Delivery[] {
    29	    const sub = this.repo.getSubscription(subscriptionId);
    30	    const today = isoDate(this.clock.now());
    31	    const dates = upcomingDeliveries(sub, today, count);
    32	    const out: Delivery[] = [];
    33	    for (const date of dates) {
    34	      if (!this.repo.find(subscriptionId, date)) {
    35	        out.push(this.repo.schedule(subscriptionId, date));
    36	      }
    37	    }
    38	    return out;
    39	  }
