    41	  /** The next delivery date the customer can still change. */
    42	  nextChangeableDelivery(subscriptionId: string): string {
    43	    const sub = this.repo.getSubscription(subscriptionId);
    44	    return nextDeliveryDate(sub, this.clock.now());
