    48	    return this.repo.deliveriesFor(customerId);
    49	  }
    50	
    51	  /**
    52	   * Process a batch of delivery events off the queue. The queue is at-least-once,
    53	   * so the same work can arrive more than once; already-processed events are skipped.
    54	   */
    55	  processQueue(events: DeliveryEvent[]): Delivery[] {
    56	    const shipped: Delivery[] = [];
    57	    for (const ev of events) {
    58	      if (this.processed.has(ev.eventId)) continue;
    59	      this.processed.add(ev.eventId);
    60	      const existing = this.repo.find(ev.subscriptionId, ev.date);
    61	      const delivery = existing ?? this.repo.schedule(ev.subscriptionId, ev.date);
    62	      if (delivery.status !== "skipped") {
    63	        this.repo.setStatus(ev.subscriptionId, ev.date, "delivered");
    64	        shipped.push(delivery);
    65	      }
    66	    }
