     1	// Domain types for the subscription-box delivery-scheduling service.
     2	//
     3	// A customer subscribes to a recurring box. Boxes ship on a cadence. Each
     4	// delivery has a *cutoff*: a local wall-clock moment, some days before the
     5	// delivery, after which the box is locked and can no longer be changed.
     6	
     7	export type Cadence = "weekly" | "biweekly" | "monthly";
     8	
     9	export type DeliveryStatus = "scheduled" | "skipped" | "queued" | "delivered";
    10	
    11	export interface Subscription {
    12	  id: string;
    13	  customerId: string;
    14	  /** IANA timezone the customer's cutoff is expressed in, e.g. "America/Los_Angeles". */
    15	  timezone: string;
    16	  cadence: Cadence;
    17	  /** ISO date (YYYY-MM-DD) of the first delivery in the series. */
    18	  anchorDate: string;
    19	  /** Local hour (0-23) on the cutoff day after which the box locks. */
    20	  cutoffHour: number;
    21	  /** How many days before a delivery the cutoff falls (typically 2). */
    22	  cutoffDaysBefore: number;
    23	  active: boolean;
    24	}
    25	
    26	export interface Delivery {
    27	  subscriptionId: string;
    28	  customerId: string;
    29	  /** ISO date (YYYY-MM-DD) this box ships. */
    30	  date: string;
    31	  status: DeliveryStatus;
    32	}
    33	
    34	/** An at-least-once delivery-processing event off the queue. */
    35	export interface DeliveryEvent {
    36	  /** Transport-level id. A retry of the same work arrives with a NEW eventId. */
    37	  eventId: string;
    38	  subscriptionId: string;
    39	  date: string;
    40	}
    41	
    42	export class UnknownSubscriptionError extends Error {
    43	  constructor(id: string) {
    44	    super(`no subscription ${id}`);
    45	    this.name = "UnknownSubscriptionError";
    46	  }
    47	}
    48	
    49	export class DuplicateDeliveryError extends Error {
    50	  constructor(key: string) {
    51	    super(`a delivery already exists for ${key}`);
    52	    this.name = "DuplicateDeliveryError";
    53	  }
    54	}
    55	
    56	export class DeliveryNotFoundError extends Error {
    57	  constructor(key: string) {
    58	    super(`no delivery for ${key}`);
    59	    this.name = "DeliveryNotFoundError";
    60	  }
    61	}
